@startuml

class Faculty {
  + name : string
}

class Institute {
  + name : string
  + address : string
}

class Employee {
  + ssn : string
  + name : string
  + email : string
}

class ResearchAssistant extends Employee {
  + researchField : string
}

class Lecturer extends ResearchAssistant {}

class Course {
  + id : int
  + name : string
  + weeklyDuration : int
}

class Project {
  + name : string
  + startDate : date
  + endDate : date
}

class ProjectInvolvement {
  + hours : int
}

Faculty "1" -- "*" Institute : is made up of
Faculty "1" -- "1" Employee : is headed by
Employee "1" -- "*" Employee : total number of employees
ResearchAssistant "*" -- "1..*" Institute : is assigned to
ResearchAssistant "1" -- "*" ProjectInvolvement : involved in
Project "1" -- "*" ProjectInvolvement : has
Lecturer "1" -- "*" Course : teaches

@enduml

